SELECT

FROM ANYI_USER_TASK ali


     AND ali.TASK_ID = #{query.userTaskKey, jdbcType=VARCHAR}


     AND ali.TASK_DEFINITION_KEY = #{query.elementId, jdbcType=VARCHAR}


     AND ali.TASK_NAME = #{query.name, jdbcType=VARCHAR}


     AND ali.PROCESS_DEFINITION_ID = #{query.processDefinitionId, jdbcType=VARCHAR}


     AND ali.START_TIME = #{query.creationDate, jdbcType=TIMESTAMP}


     AND ali.END_TIME = #{query.completionDate, jdbcType=TIMESTAMP}


     AND ali.ASSIGNEE = #{query.assignee, jdbcType=VARCHAR}


     AND ali.STATE = #{query.state, jdbcType=VARCHAR}


     AND ali.DEFINITION_KEY = #{query.processDefinitionKey, jdbcType=VARCHAR}


     AND ali.PROCESS_INSTANCE_ID = #{query.processInstanceKey, jdbcType=VARCHAR}


     AND ali.ACTIVITY_INSTANCE_ID = #{query.elementInstanceKey, jdbcType=VARCHAR}


     AND ali.DUE_TIME = #{query.dueDate, jdbcType=TIMESTAMP}


     AND ali.FOLLOW_UP_TIME = #{query.followUpDate, jdbcType=TIMESTAMP}


     AND ali.PRIORITY = #{query.priority, jdbcType=INTEGER}

